Tri Principe Stable ? Pire cas Moyen Meilleur Sélection À chaque tour, placer le min restant Non O(n²) O(n²) O(n²) Insertion Insérer chaque élément à sa place dans la partie triée Oui O(n²) O(n²) O(n) Fusion Diviser, trier, fusionner Oui O(n log n) O(n log n) O(n log n) Rapide (quicksort) Choisir pivot, partitionner Non O(n²) O(n log n) O(n log n) <pre><code>def tri_insertion(t):
    for i in range(1, len(t)):
        x, j = t[i], i
        while j &gt; 0 and t[j-1] &gt; x:
            t[j] = t[j-1]
            j -= 1
        t[j] = x

def tri_fusion(t):
    if len(t) &lt;= 1: return t
    m = len(t) // 2
    g, d = tri_fusion(t[:m]), tri_fusion(t[m:])
    return fusion(g, d)

def fusion(a, b):
    res, i, j = [], 0, 0
    while i &lt; len(a) and j &lt; len(b):
        if a[i] &lt;= b[j]:
            res.append(a[i]); i += 1
        else:
            res.append(b[j]); j += 1
    return res + a[i:] + b[j:]
